const DataProvider = {
  async getDecades() {
    return DECADES.filter((d) => Object.keys(ROSTERS[d] || {}).length > 0);
  },
  async getTeams(decade) {
    return Object.keys(ROSTERS[decade] || {});
  },
  async getRoster(decade, team) {
    return (ROSTERS[decade] && ROSTERS[decade][team]) || [];
  },
};
